result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/parser.ts", "content": "// Command parser for interactive fiction.
// Grammar: [verb] [object] ([preposition] [object2])?

export type ParseSuccess = {
  ok: true;
  verb: string;
  obj?: string;
  prep?: string;
  obj2?: string;
};

export type ParseError =
  | { ok: false; error: "empty-input" }
  | { ok: false; error: "unknown-verb"; word: string }
  | { ok: false; error: "missing-object"; verb: string };

export type ParseResult = ParseSuccess | ParseError;

/** Canonical verbs -> accepted synonyms (all lowercased). */
const VERB_SYNONYMS: Record<string, readonly string[]> = {
  take: ["get", "grab", "pick", "pick-up", "pickup"],
  "look-at": ["examine", "inspect", "x", "l"],
  go: ["walk", "run", "move", "head"],
  put: ["place", "insert", "drop-in"],
  open: ["unlock"], // loose synonym; fine for a quick parser
  look: ["ls"],
  inventory: ["i", "inv"],
};

const VERB_LOOKUP: Map<string, string> = new Map(
  Object.entries(VERB_SYNONYMS).flatMap(([canonical, syns]) => [
    [canonical, canonical],
    ...syns.map((s) => [s, canonical]),
  ])
);

const PREPOSITIONS = new Set([
  "in",
  "into",
  "on",
  "onto",
  "at",
  "with",
  "under",
  "from",
  "to",
]);

const ARTICLES = new Set(["the", "a", "an"]);

function stripArticles(words: string[]): string {
  return words.filter((w) => !ARTICLES.has(w)).join(" ");
}

export function parse(input: string): ParseResult {
  const tokens = input
    .toLowerCase()
    .split(/\s+/)
    .filter((t) => t.length > 0 && t !== ",");

  if (tokens.length === 0) {
    return { ok: false, error: "empty-input" };
  }

  const first = tokens[0];
  const verb = VERB_LOOKUP.get(first);
  if (verb === undefined) {
    return { ok: false, error: "unknown-verb", word: first };
  }

  const rest = tokens.slice(1);
  if (verb === "inventory" || verb === "look") {
    return rest.length === 0 ? { ok: true, verb } : { ok: true, verb, obj: stripArticles(rest) };
  }

  // Find preposition split point.
  let prepIndex = -1;
  for (let i = 0; i < rest.length; i++) {
    if (PREPOSITIONS.has(rest[i])) {
      prepIndex = i;
      break;
    }
  }

  if (prepIndex === -1) {
    const objWords = rest;
    if (objWords.length === 0) {
      return { ok: false, error: "missing-object", verb };
    }
    return { ok: true, verb, obj: stripArticles(objWords) };
  }

  const obj = stripArticles(rest.slice(0, prepIndex));
  const prep = rest[prepIndex];
  const obj2 = stripArticles(rest.slice(prepIndex + 1));

  if (obj.length === 0 || obj2.length === 0) {
    return { ok: false, error: "missing-object", verb };
  }

  return { ok: true, verb, obj, prep, obj2 };
}
"})
