result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/parser.test.ts", "content": "import { describe, expect, it } from "vitest";
import { parse, type ParseResult } from "./parser";

interface Vector {
  name: string;
  input: string;
  expected: ParseResult;
}

const vectors: Vector[] = [
  {
    name: "simple take with article and adjective noun",
    input: "take the brass key",
    expected: { ok: true, verb: "take", obj: "brass key" },
  },
  {
    name: "put with preposition phrase",
    input: "put coin in slot",
    expected: { ok: true, verb: "put", obj: "coin", prep: "in", obj2: "slot" },
  },
  {
    name: "synonym x maps to look-at",
    input: "x lamp",
    expected: { ok: true, verb: "look-at", obj: "lamp" },
  },
  {
    name: "synonym examine maps to look-at",
    input: "examine the dusty tome",
    expected: { ok: true, verb: "look-at", obj: "dusty tome" },
  },
  {
    name: "synonym inspect maps to look-at with article stripped from multiword object",
    input: "inspect the old wooden chest",
    expected: { ok: true, verb: "look-at", obj: "old wooden chest" },
  },
  {
    name: "synonym grab maps to take",
    input: "grab apple",
    expected: { ok: true, verb: "take", obj: "apple" },
  },
  {
    name: "get with indefinite article",
    input: "get a red ball",
    expected: { ok: true, verb: "take", obj: "red ball" },
  },
  {
    name: "pick up two-word synonym collapses to take",
    input: "pick up the coin",
    expected: { ok: true, verb: "take", obj: "coin" },
  },
  {
    name: "insert ... into normalizes to put ... into",
    input: "insert the key into the lock",
    expected: { ok: true, verb: "put", obj: "key", prep: "into", obj2: "lock" },
  },
  {
    name: "place ... on surface",
    input: "place book on shelf",
    expected: { ok: true, verb: "put", obj: "book", prep: "on", obj2: "shelf" },
  },
  {
    name: "movement verb north",
    input: "go north",
    expected: { ok: true, verb: "go", obj: "north" },
  },
  {
    name: "bare inventory via synonym i",
    input: "i",
    expected: { ok: true, verb: "inventory" },
  },
  {
    name: "unknown verb names the offending word",
    input: "frobnicate the widget",
    expected: { ok: false, error: "unknown-verb", word: "frobnicate" },
  },
  {
    name: "empty string is empty-input error",
    input: "",
    expected: { ok: false, error: "empty-input" },
  },
  {
    name: "whitespace-only input is empty-input error",
    input: "   \t  ",
    expected: { ok: false, error: "empty-input" },
  },
  {
    name: "case is normalized",
    input: "TAKE The Brass KEY",
    expected: { ok: true, verb: "take", obj: "brass key" },
  },
  {
    name: "verb alone without object is a missing-object error",
    input: "take",
    expected: { ok: false, error: "missing-object", verb: "take" },
  },
];

describe("parse", () => {
  for (const v of vectors) {
    it(v.name, () => {
      expect(parse(v.input)).toEqual(v.expected);
    });
  }

  it("every vector has a unique name", () => {
    expect(new Set(vectors.map((v) => v.name)).size).toBe(vectors.length);
  });

  it("has at least 15 vectors", () => {
    expect(vectors.length).toBeGreaterThanOrEqual(15);
  });
});
"})
